import { expect, test, uniqueName } from "../../fixtures";

test("vendor names are unique within a tenant, ignoring case", { tag: "@VEN-03" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const name = uniqueName("Acme Freight");
  const first = await member.post("/api/vendors", {
    data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
  });
  expect(first.status(), await first.text()).toBe(201);

  // Act
  const duplicate = await member.post("/api/vendors", {
    data: { name: name.toLowerCase(), category: "logistics", contact_email: "ops@acmefreight.example" },
  });

  // Assert
  const body = await duplicate.text();
  expect(duplicate.status(), body).toBe(409);
  expect(JSON.parse(body).error.code, body).toBe("vendor_name_taken");
});
